'use strict';
const SUPPLY_UI5={bind,help};
let supplyWeeks5=8,supplyFactor5=1,supplyCache5=null,supplyStamp5='',supplyPurchaseDraft5=[];
TITLES.supply='Plán zásobování & výroby';
function supplyResult5(){const stamp=JSON.stringify(state)+'|'+supplyWeeks5+'|'+supplyFactor5;if(stamp!==supplyStamp5){supplyCache5=supplyForecast5(supplyWeeks5,supplyFactor5);supplyStamp5=stamp;}return supplyCache5;}
function supplyTimeline5(result){const max=Math.max(1,...result.series.map(s=>s.cities.reduce((a,c)=>a+c.need,0)));return `<div class="supply-chart5" role="img" aria-label="Odhad potřeby kávy a skutečně pokryté spotřeby podle týdnů">${result.series.map(s=>{const need=s.cities.reduce((a,c)=>a+c.need,0),used=s.cities.reduce((a,c)=>a+c.used,0),loss=s.cities.reduce((a,c)=>a+c.lost,0);return `<div><div class="supply-bars5"><i style="height:${need/max*120}px"></i><b style="height:${used/max*120}px"></b></div><strong>T${s.week}</strong><small>${number(need,1)} kg potřeba</small><small class="${loss?'bad':''}">${loss?loss+' hostů bez kávy':'Pokrytá spotřeba'}</small></div>`}).join('')}</div><p class="sub supply-legend5">Světlá: potřeba kaváren · tmavá: pokrytá spotřeba. Kontrakty a e-shop jsou navíc součástí simulace výroby.</p>`;}
function supplyView(){const f=supplyResult5(),latest=f.series[0],activePlan=state.supply5.plans.length;return `<div class="view-toolbar"><p class="intro">Naplánuj kávu před dalším tahem. Výhled počítá stejnou firmu, dodávky a pravidla jako hra.</p><div class="fields">${field('Horizont',`<select id="supplyWeeks5">${[4,8,13].map(n=>option(n,n+' týdnů',supplyWeeks5)).join('')}</select>`)}${field('Varianta návštěvnosti',`<select id="supplyFactor5">${option(.85,'Nižší · −15 %',supplyFactor5)}${option(1,'Základní',supplyFactor5)}${option(1.15,'Vyšší · +15 %',supplyFactor5)}</select>`)}</div></div><div class="report-overview5">${metric('PRVNÍ VÝPADEK',f.firstLoss===null?'Žádný':'Týden '+f.firstLoss,f.lost+' hostů bez kávy ve výhledu',f.lost?'bad':'')}${metric('EXPRESNÍ NÁKUPY',money(f.expressCost),'Zrna včetně přirážky 18 %')}${metric('HOTOVOST NA KONCI',money(f.finalCash),f.series.length+' spočítaných týdnů',f.finalCash<0?'bad':'')}${metric('VÝROBNÍ PLÁNY',activePlan+'/'+state.roasters.length,'Neobsazené plány používají původní pravidla')}</div>${f.over?'<div class="warning">Výhled končí platební neschopností nebo ukončením firmy. Další týdny nejsou dopočítané.</div>':''}<div class="split"><section class="card"><div class="card-head"><h2>Spotřeba v příštích týdnech</h2><span class="badge">Od týdne ${f.week}</span></div>${f.series.length?supplyTimeline5(f):empty('Firma nepokračuje; načti jiný postup pro nový výhled.')}<p class="sub">Základní varianta pokračuje současnými pravidly bez dalších ručních zásahů. Výhled zohledňuje i budoucí mzdy, odpisy, sklizně, směny a rozhodnutí soupeřů.</p></section><section class="card"><h2>Co může zastavit dodávky</h2>${f.alerts.length?f.alerts.slice(0,7).map(a=>`<div class="news"><span class="news-icon">T${a.week}</span><div><strong>${esc(a.target)}</strong><small>${esc(a.text)}</small></div></div>`).join(''):'<p class="empty">V této variantě nehrozí výpadek kávy, pozastavení pražení ani odpis.</p>'}<div class="actions"><button class="primary" id="prepareSupply5" ${state.over?'disabled':''}>Připravit nákup zrn</button><button class="soft" data-goto="logistics">Sklady a trasy</button></div><p class="sub">Běžná objednávka přijede v týdnu ${state.week+1}. Nedostatek při nejbližším tahu v týdnu ${state.week} vyžaduje dostupná zrna nebo povolený expres.</p></section></div><section class="card" style="margin-top:24px"><h2>Zelená zrna a příchozí dodávky</h2><div class="table-scroll"><table class="data supply-table5"><thead><tr><th>Původ</th><th>Zásoba dnes</th><th>Na cestě</th><th>Potřeba ve výhledu</th><th>Expres ve výhledu</th></tr></thead><tbody>${Object.entries(ORIGINS).map(([key,o])=>`<tr><td>${esc(o.name)}</td><td>${number(greenAmount(key),1)} kg</td><td>${number(state.shipments.filter(s=>s.origin===key).reduce((a,s)=>a+s.kg,0),1)} kg</td><td>${number(f.greenUsed[key],1)} kg</td><td>${number(f.series.reduce((a,s)=>a+s.express[key].kg,0),1)} kg</td></tr>`).join('')}</tbody></table></div><details><summary>Termíny dodávek a sklizní ve výhledu</summary>${f.series.flatMap(s=>Object.entries(s.arrivals).filter(([k,n])=>n>.001).map(([k,n])=>`<div class="row"><span>Týden ${s.week} · ${esc(ORIGINS[k].name)}</span><strong>${number(n,1)} kg</strong></div>`)).join('')||'<p class="sub">V této variantě žádná zásilka zelených zrn nepřijíždí.</p>'}<p class="sub">Zobrazené jsou skutečné příjezdy do skladu v simulaci, včetně plánovaných nákupů, rámcových smluv a sklizní.</p></details></section><section class="card" style="margin-top:24px"><h2>Pokrytí kaváren podle měst</h2><div class="table-scroll"><table class="data supply-table5"><thead><tr><th>Město</th><th>Potřeba příštího tahu</th><th>Zásoba po příštím tahu</th><th>První výpadek</th><th>Hosté bez kávy ve výhledu</th></tr></thead><tbody>${(latest?.cities||[]).map(c=>{const first=f.series.find(s=>s.cities.some(x=>x.city===c.city&&x.lost)),lost=f.series.reduce((a,s)=>a+(s.cities.find(x=>x.city===c.city)?.lost||0),0);return `<tr><td>${esc(c.city)}</td><td>${number(c.need,1)} kg</td><td>${number(c.stock,1)} kg</td><td class="${first?'bad':''}">${first?'Týden '+first.week:'Bez výpadku'}</td><td>${lost}</td></tr>`}).join('')||'<tr><td colspan="5">Výhled není dostupný.</td></tr>'}</tbody></table></div><p class="sub">U expresního zásobování může město prodávat i kávu z jiných skladů. U plánovaných tras záleží na místní zásobě, době přepravy a volném prostoru. Více zelených zrn samo nenahradí chybějící pražírnu nebo trasu.</p></section><div class="section-header"><h2>Pravidla automatické výroby</h2><button class="soft" data-goto="roasters">Směny, lidé a servis</button></div><div class="cards">${state.roasters.map(r=>{const p=productionPlan5(r),rows=f.series.flatMap(s=>s.roasters.filter(x=>x.id===r.id).map(x=>({...x,week:s.week}))),peak=Math.max(0,...rows.map(x=>x.capacity?x.used/x.capacity:0)),blocked=rows.find(x=>x.holds);return `<section class="card"><div class="card-head"><h3>${esc(r.name)}</h3><span class="badge">${r.auto?'Automatická výroba':'Ruční výroba'}</span></div><p class="sub">${esc(r.zone)} · kapacita nyní ${roasterCapacity(r)} kg zelených zrn / týden</p>${rows.length?`<p class="sub">Nejvyšší využití ve výhledu ${number(peak*100,1)} %${blocked?' · pozastavení v týdnu '+blocked.week:''}.</p>`:''}<div class="fields">${field('Cílová zásoba (týdny odběru)',`<input type="number" step="0.05" min="0.5" max="3" value="${p.buffer}" data-production="${r.id}" data-production-key="buffer">`)}${field('Limit nákupu a zpracování / týden',`<input type="number" step="1000" min="0" max="500000" value="${p.limit}" data-production="${r.id}" data-production-key="limit">`)}${field('Zachovat rezervu (týdny)',`<input type="number" step="0.1" min="1" max="8" value="${p.reserve}" data-production="${r.id}" data-production-key="reserve">`)}</div><label class="checkbox-line"><input type="checkbox" data-production="${r.id}" data-production-key="allowExpress" ${p.allowExpress?'checked':''}> Povolit expresní nákup chybějících zrn</label><div class="actions"><button class="primary" data-production-save="${r.id}" ${state.over?'disabled':''}>Uložit výrobní plán</button><button class="quiet" data-production-reset="${r.id}" ${state.over?'disabled':''}>Vrátit původní pravidla</button></div><p class="sub">Limit zahrnuje expresní zrna a 55 Kč zpracování / kg zelené kávy. Mzdy, servis a předem objednaná zrna se účtují samostatně. Bez dostatečného limitu nebo rezervy se šarže odloží. Plán se spustí jen při zapnuté automatické výrobě.</p></section>`}).join('')}</div>`;}
function supplyPurchaseDialog5(){const f=supplyResult5();supplyPurchaseDraft5=f.recommendations.map(o=>({origin:o.origin,kg:o.kg})).filter(o=>o.kg);show(`<h2>Nákupní návrh zrn</h2><p class="sub">Návrh nahrazuje očekávané expresní nákupy v týdnech ${state.week+1} a ${state.week+2}. Nejbližší tah objednávka nezachrání. Množství lze upravit; nejprve porovnej výhled.</p><div class="fields">${Object.entries(ORIGINS).map(([k,o])=>field(o.name,`<input type="number" min="0" max="2500" value="${supplyPurchaseDraft5.find(x=>x.origin===k)?.kg||0}" data-supply-order="${k}">`)).join('')}</div><div class="actions"><button class="soft" id="supplyCompare5">Porovnat nákup ve výhledu</button><button class="primary" id="supplyBuy5">Objednat vybraná zrna</button></div><div id="supplyComparison5" class="supply-comparison5"></div><p class="sub">Celá objednávka zachová rezervu na dva týdny fixních nákladů. Pokud peníze nebo údaje nesedí, žádná položka se neobjedná.</p>`);
 const read=()=>[...document.querySelectorAll('[data-supply-order]')].map(n=>({origin:n.dataset.supplyOrder,kg:Number(n.value)})).filter(o=>o.kg!==0);
 el('supplyCompare5').onclick=()=>{try{const orders=read(),quote=supplyOrderQuote5(orders),alternative=supplyForecast5(supplyWeeks5,supplyFactor5,orders);el('supplyComparison5').innerHTML=rows([['Cena objednávky',money(quote.total)],['Příjezd', 'Týden '+(state.week+1)],['Expresní nákupy po změně',money(alternative.expressCost)+' (původně '+money(f.expressCost)+')'],['Hosté bez kávy po změně',alternative.lost+' (původně '+f.lost+')'],['Hotovost na konci',money(alternative.finalCash)]])}catch(e){el('supplyComparison5').textContent=e.message}};
 el('supplyBuy5').onclick=()=>{try{const orders=read(),quote=supplyOrderQuote5(orders);confirmAction('Objednat zrna za '+money(quote.total)+'?','Příjezd v týdnu '+(state.week+1)+'. Zůstane nejméně dvoutýdenní rezerva. Nákup je skutečný výdaj firmy.',()=>placeSupplyOrders5(orders,2,quote),'Objednat')}catch(e){toast(e.message)}};
}
bind=function(){SUPPLY_UI5.bind();if(el('supplyWeeks5'))el('supplyWeeks5').onchange=()=>{supplyWeeks5=Number(el('supplyWeeks5').value);render()};if(el('supplyFactor5'))el('supplyFactor5').onchange=()=>{supplyFactor5=Number(el('supplyFactor5').value);render()};if(el('prepareSupply5'))el('prepareSupply5').onclick=supplyPurchaseDialog5;on('[data-production-save]',b=>act(()=>{const id=b.dataset.productionSave,data={};document.querySelectorAll(`[data-production="${id}"]`).forEach(n=>data[n.dataset.productionKey]=n.type==='checkbox'?n.checked:Number(n.value));setProductionPlan5(id,data)},'Výrobní plán uložen.'));on('[data-production-reset]',b=>act(()=>resetProductionPlan5(b.dataset.productionReset),'Obnovena původní pravidla.'));};
help=function(){SUPPLY_UI5.help();const p=document.createElement('p');p.textContent='Plán zásobování simuluje 4, 8 nebo 13 příštích týdnů v kopii firmy. Zvol variantu poptávky, prohlédni výpadky, sklizně a vytížení pražíren. Nákupní návrh umožní porovnat skutečnou objednávku před zaplacením. Běžné dodání trvá do následujícího týdne. Výrobní plán mění cílovou zásobu, limit variabilních výdajů, rezervu a povolení expresu; ruční pražírny se samy nezapnou.';el('modalContent').append(p)};el('help').onclick=help;
render();
